namespace ShieldReport.Application.Reports.Dtos;

public sealed record ReportDto(
    long Id,
    Guid PublicId,
    long EngagementId,
    long ReportTemplateId,
    int Version,
    string Status,
    string ExecutiveSummary,
    string KeyFindings,
    string KeyRecommendations,
    bool DraftAvailable,
    bool PdfAvailable,
    long GeneratedByUserId,
    DateTime GeneratedAt,
    long? ApprovedByUserId,
    DateTime? ApprovedAt,
    long? RejectedByUserId,
    DateTime? RejectedAt,
    string? RejectionReason,
    // HTML engine fields (empty/false for reports generated by the legacy .docx engine).
    string ProjectGoals,
    string Limitations,
    IReadOnlyDictionary<long, string> ScopeStatuses,
    bool ShowToolNames,
    bool HasHtmlPreview,
    // Manual | Drafting | Drafted | Failed (see ReportNarrativeStatus).
    string NarrativeStatus,
    string? NarrativeError,
    string? TemplateName,
    // The template's dynamic fields and this report's values for them.
    IReadOnlyList<ShieldReport.Application.ReportTemplates.ReportTemplateField>? CustomFields = null,
    IReadOnlyDictionary<string, string>? CustomFieldValues = null
);

public sealed record ReportPreviewRequestDto(long? TemplateId = null, ShieldReport.Domain.Enums.TestingType? TestingType = null, bool ShowToolNames = false, Dictionary<string, string>? CustomFieldValues = null);

// Per-report editable sections beyond the three narrative fields (see ReportSectionDefaults).
public sealed record UpdateReportSectionsRequestDto(
    string ProjectGoals,
    string Limitations,
    Dictionary<long, string>? ScopeStatuses,
    bool ShowToolNames,
    Dictionary<string, string>? CustomFieldValues = null);

// Engine: "Html" (preview available) or "Word" (legacy uploaded .docx, no preview).
// CustomFields: the template's dynamic fields, filled in the Generate dialog.
public sealed record ReportTemplateOptionDto(long Id, string Name, string Engine, bool IsCustomHtml, ShieldReport.Domain.Enums.TestingType? BuiltInTestingType, IReadOnlyList<ShieldReport.Application.ReportTemplates.ReportTemplateField> CustomFields);
